void recalculate_apic_map(struct kvm *kvm) {
    struct kvm_apic_map *old_map, *new_map;
    struct kvm_vcpu *vcpu;

    old_map = kvm->apic_map;
    new_map = kzalloc(sizeof(*new_map), GFP_KERNEL);

    if (!new_map) {
        return;
    }

    kvm_for_each_vcpu(vcpu, kvm) {
        int id = kvm_apic_id(vcpu->apic);
        new_map->phys_map[vcpu->vcpu_id] = id;
    }

    kvm->apic_map = new_map;
    kfree(old_map);
}

